INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Halibut, Atlantic', 'Common Halibut, Giant Hhalibut, Righteye Flounder', 'Halibut is a common name principally applied to the two flatfish in the genus Hippoglossus from the family of right-eye flounders. Less commonly, and in some regions only, other species of flatfish are also referred to as being halibuts. The word is derived from haly (holy) and butte (flat fish), for its popularity on Catholic holy days. Halibut are demersal fish and are highly regarded as a food fish.
The Atlantic halibut is a right-eyed flounder. It is flattened sideways and habitually lies on the left side of its body with both eyes migrating to the right side of its head during development. Its upper surface is a uniformly dark chocolate, olive or slate colour, and can be almost black; the underside is pale. The end of the caudal fin is concave. Young fish are paler with more mottled coloration.
The lateral line, which has a scale count of about 160, arches strongly above the pectoral fin. The teeth are equally well developed in both sides of the jaw. This species is usually pearly white and featureless on the blind side. Some specimens, nicknamed “cherry bellies”, have a reddish tint on the blind side.', 'Pleuronectidae', 'Hippoglossus hippoglossus', 'Endangered', 'The Atlantic halibut inhabits cold and boreal waters of the North Atlantic, including the Barents Sea, Iceland, and Greenland. It is also found in very deep, cold waters as far south as Virginia on the American side and southwest Ireland on the European side. This species does not occur in near freezing polar waters as many people believe, but is replaced there by the Greenland halibut, Reinhardtius hippoglossoides.

Atlantic Halibut make extensive migrations and interchanges occur between stocks in North America and Iceland, and among stocks in Iceland, the Faeroe Islands and the North Sea.', 'Atlantic halibut feed in midwater as well as on the bottom. The best fishing method is drift fishing on the bottom with heavy tackle, but they can be caught on fly.

The halibut is a strong fighter and a valuable food fish. The flesh is of good quality and texture', 'The Atlantic halibut has a relatively slow growth rate and late onset of sexual maturity, with males attaining maturity at seven to eight years old, females at 10 to 11 years, and individuals are thought to live up to 50 years. Little is known about their breeding except their spawning is seasonal, although its timing varies somewhat with location. In the eastern Atlantic, spawning occurs chiefly in March, April and May, although may span from January to June. Off the American coast, however, the spawning season appears to continue through the summer as late as September.', 'The young feed primarily on crustaceans. Adults have been known to feed on sand lance, octopus, crab, salmon, hermit crabs, lamprey, sculpin, cod, pollock, herring, and flounder, as well as other halibut. Stomach contents indicate that large halibut feed in midwater as well as near the bottom. In most ecosystems, the halibut is near the top of the marine food chain.', 'Ocean', 'Fight Dynamics', '418 lb 13 oz,
Thomas Nielsen,
Vannaya Troms, Norway,
7/28/2004', 'Atlantic Halibut WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Halibut, Pacific', 'Northern Halibut, Right Hhalibut, Alabato', 'Halibut is a common name principally applied to the two flatfish in the genus Hippoglossus from the family of right-eye flounders. Less commonly, and in some regions only, other species of flatfish are also referred to as being halibuts. The word is derived from haly (holy) and butte (flat fish), for its popularity on Catholic holy days. Halibut are demersal fish and are highly regarded as a food fish.
Pacific halibut are dark brown on the top side with an off-white underbelly and have very small scales invisible to the naked eye embedded in their skin. At birth, they have an eye on each side of the head, and swim like a salmon. After six months, one eye migrates to the other side, making them look more like flounder. At the same time, the stationary-eyed side darkens to match the top side, while the other side remains white. This color scheme disguises halibut from above (blending with the ocean floor) and from below (blending into the light from the sky) and is known as countershading. The teeth are strong and equally well developed on both sides of the jaws.
Females grow to weights of over 470 lb (213 kg), live to a maximum age of 35 to 45 years and may attain a length of 9 ft (3 m). By comparison, males probably do not exceed 40 lb (18 kg) or 55 in (140 cm), and their maximum life expectancy appears to be about 25 years. The females are more numerous than the males and grow faster, except during the early stages of development.
The Pacific halibut is the world''s largest flatfish and very much resembles the Atlantic halibut, Hippoglossus hippoglossus.. The IGFA record was apparently broken off the waters of Norway in July 2013 by a 515-pound 8.6 foot fish. This is awaiting certification as of 2013. In July 2014, 76-year-old Jack McGuire caught a 482-pound Pacific halibut in Glacier Bay, Alaska (this is, however, discounted from records because it was shot to prevent injury to those on the boat).', 'Pleuronectidae', 'Hippoglossus stenolepis', 'Not Evaluated', 'The Pacific halibut occurs in the cold waters of the North Pacific from the Bering Sea south to about Santa Rosa Island, California, on the American side and to northern Japan (including the Okhotsk Sea) on the Asian side. The Pacific halibut is highly migratory. Tagging operations have shown that some adult specimens travel 2,000 miles or more, though others appear to remain near the spawning grounds. In northern areas large halibut can be found in relatively shallow waters, but in the warmer southern portions of their range they may go as deep as 600 fathoms or more.', 'Halibut can be caught while drift fishing on the bottom with heavy tackle, using baits like cod, herring, squid, mackerel or smaller flatfishes.', 'Spawning takes place during the winter months, with the peak of activity occurring from December through February. Most spawning takes place off the edge of the continental shelf in deep waters of 600 to 1,500 ft (183 to 457 m). Male halibut become sexually mature at seven to eight years of age, while females attain sexual maturity at eight to 12 years. Females lay 0.5 to 4.0 million eggs annually, depending on the size of the fish.

Fertilized eggs hatch after about 15 days. Free-floating larvae float for up to six months and can be transported several hundred miles counter-clockwise by North Pacific currents. During the free-floating stage, many changes take place in the young halibut, including the movement of the left eye to the right side of the fish. During this time, the young halibut rise to the surface and are carried to shallower water by prevailing currents. At six months, the halibut has its adult form and is about 1.4 in (3.6 cm) long. In the shallower water, young halibut then begin life as bottom dwellers. Most young halibut ultimately spend from five to seven years in rich, shallow nursery grounds such as the Bering Sea.

Young halibut are highly migratory and generally migrate in a clockwise direction east and south throughout the Gulf of Alaska. Halibut in older age classes tend to be less migratory, but continue to move predominately on a clockwise direction. Mature fish are also involved in winter spawning migrations towards deeper waters, migrating across several areas in some instances. Research has indicated small, localized spawning populations may occur in deep waters such as in Chatham Straight in northern Southeast Alaska. However, because of the free-floating nature of larvae and subsequent mixing of juvenile halibut from throughout the Gulf of Alaska, only one genetic stock of halibut is known in the northern Pacific.', 'The young feed primarily on crustaceans. Adults have been known to feed on sand lance, octopus, crab, salmon, hermit crabs, lamprey, sculpin, cod, pollock, herring, and flounder, as well as other halibut. Stomach contents indicate that large halibut feed in midwater as well as near the bottom.

In most ecosystems, the halibut is near the top of the marine food chain. In the North Pacific, their common predators are the sea lion (Eumetopias jubatus), the killer whale (Orcinus orca), and the salmon shark (Lamna ditropis).', 'Ocean', 'Fight Dynamics', '459 lb,
Jack Tragis,
Dutch Harbor, Alaska, USA,
6/11/1996', 'Pacific Halibut WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Threadfin, King', 'Burnett’s Salmon, King Salmon, King Threadfin Salmon, Threadfin, Threadfin Salmon, Thready', 'King threadfin have a bluish-silver back and a whitish belly (during some seasons the belly surface is flushed with yellow). Their dorsal, anal and caudal fins are blackish with the pectoral fins, pelvic fins and pectoral filaments being in the white to yellow range.', 'Polynemidae', 'Polydactylus macrochir', 'Not Evaluated', 'King Threadfin are popular recreational species in Western Australia, Northern Queensland and increasingly South-East Queensland. With the species now being found further South down the East coast of Australia, many more recreational anglers are targeting them and as a result they have been included as a category in the Brisbane River Classic fishing competition.

King Threadfin are found in coastal estuaries, river mouths and sand and mud flats to a depth of 20 ft.', 'For many anglers a baitcaster and lure is the way to chase threadies, but bait anglers could use a medium spinning outfit baited with a fish fillet, prawn or live bait. 

Sporting anglers may fish as light as 6kg in relatively clear water but given the initial powerful runs you will experience with a decent threadfin, perhaps 8-10kg is the way to go. 15kg braid can help stop a decent fish from burying you in snags.

Sight casting lures for threadfin is highly recommended, but not always possible, or successful. Blind casting to small run-offs and color changes in the water is more likely to result in a hookup. 

Boat anglers can troll for threadfin, but this should be done slowly as a strike from a decent thready can be quite deceiving at times. It can feel far more like a snag than a strike as they take your lure slowly. 

Generally shallow running lures are best for casting around dropoffs and sandbanks. Lures such as Bombers (especially in gold), Scorpions (especially in fluoro colours), Rapala Husky Jerks and Nilsmaster Spearheads are all proven fish-takers. Trolling lures would include Halco Scorpions, Classic Lures and Tilsans. 

Slow, twitching retrieves seem to work best for many anglers, but every fish can have a different preference so just keep casting and keep varying things. 

Bait anglers can fish the same locations and wait for the fish as they move past on their way up or down the creek with the tide. A well-presented live bait can also present a decent chance of catching several other species as well.', 'Spawning on the east coast Australian populations occurs from October to early March.', 'King threadfin eat mainly seasonally abundant prawns, small fish and other small crustaceans.', 'Ocean', 'Aerial Acrobatics', '27 lb 8 oz,
Brian Albert,
Dampier Creek, Broome, Australia,
4/24/1996', 'King Threadfin WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Bluefish', 'Blues, Choppers, Fatbacks, Greenfish, Hatteras Blues, Skipjacks, Slammers, Snappers, Tailors, Taylors', 'One of only three species in its family, this piranha of the seas can be caught in subtropical and temperate coastal zones around the world. Bluefish are popular with shore and boat anglers alike in southern Australia (where they’re known as tailor), as well as in the U.S. Northeast and mid-Atlantic regions. 

The bluefish is a moderately proportioned fish, with a broad, forked tail. The spiny first dorsal fin is normally folded back in a groove, as are its pectoral fins. Coloration is a grayish blue-green dorsally, fading to white on the lower sides and belly. Its single row of teeth in each jaw is uniform in size, knife-edged, and sharp. Bluefish commonly range in size from seven-inch (18-cm) "snappers" to much larger, sometimes weighing as much as 40 lb (18 kg), though fish heavier than 20 lb (9 kg) are exceptional.

The all-tackle record of 31 pounds, 12 ounces came from Hatteras, North Carolina, in 1972.', 'Pomatomidae', 'Pomatomus saltatrix', 'Vulnerable', 'Bluefish are widely distributed around the world in tropical and subtropical waters. They are found in pelagic waters on much of the continental shelves along eastern America (though not between south Florida and northern South America), Africa, the Mediterranean and Black Seas (and during migration in between), Southeast Asia, and Australia. 

They are found in a variety of coastal habitats: above the continental shelf, in energetic waters near surf beaches, or by rock headlands. They also enter estuaries and inhabit brackish waters. Periodically, they leave the coasts and migrate in schools through open waters.

Along the U.S. East Coast, bluefish are found off Florida in the winter. By April, they have disappeared, heading north. By June, they may be found off Massachusetts; in years of high abundance, stragglers may be found as far north as Nova Scotia. By October, they leave the waters north of New York City, heading south (whereas some bluefish, perhaps less migratory, are present in the Gulf of Mexico throughout the year). 

In a similar pattern overall, the economically significant population that spawns in Europe''s Black Sea migrates south through Istanbul (Bosphorus, Sea of Marmara, Dardanelles, Aegean Sea) and on toward Turkey''s Mediterranean coast in the autumn for the cold season. Along the South African coast and environs, movement patterns are roughly in parallel.', 'With a mouthful of razor teeth and a vicious, voracious attitude to match, roving packs of bluefish are slash-and-burn predators that churn through schools of baitfish, boiling the surface. 

Fishermen typically present natural baits on a size 3/0 or 4/0 hook, sometimes followed by a smaller "stinger" hook. These are attached to wire tippets about 6 inches long, which are attached either by swivel or Albright Special to 3 to 5 feet (1.5 m) of 50 to 80 pound monofilament leader. 

Larger hooks are appropriate for larger baits and bluefish. Some fishermen instead choose only a heavy monofilament leader attached to a long-shank hook, which usually avoids the bluefish''s sharp teeth. 

Although it’s hard to beat live bait for blues, they’re likely to strike anything moving. Bluefish are known to strike just about any type of lure. Topwater plugs, such as bottleneck and pencil poppers offer anglers the most exciting lure strikes, as the bluefish will smack the lures with spectacular ferocity. Metal lures, such as Hopkins, Kastmaster, AOK, AVA and Crocodile will catch bluefish in almost all situations. Artificial lures should be presented with steel leaders to help stop the fish''s razor sharp teeth from slicing through normal fishing line.

Medium-light to medium weight spinning or bait-casting rigs are standard. 8 to 12 pound test line is common when targeting bluefish in the 1 to 3 pound range, while 20 pound test and matched tackle may be the choice when targeting larger specimens,

Fierce fighters, bluefish occasionally jump when hooked. Some anglers find them delicious; others avoid the strong, dark flesh.', 'Bluefish reproduce during spring and summer, and can live up to 9 years in age. Bluefish fry are zooplankton, and are largely at the mercy of currents. Spent bluefish have been found off east-central Florida, migrating north. As with most marine fish, their spawning habits are not well known. In the western side of the North Atlantic, at least two populations occur, separated by Cape Hatteras in North Carolina. The Gulf Stream can carry fry spawned to the south of Cape Hatteras to the north, and eddies can spin off, carrying them into populations found off the coast of the mid-Atlantic, and the New England states.', 'Adult bluefish are strong and aggressive, and live in loose groups. They are fast swimmers which prey on schools of forage fish, and continue attacking them in feeding frenzies even after they appear to have eaten their fill.

Depending on area and season, they favor menhaden and other sardine-like fish (Clupeidae), jacks (Scombridae), weakfish (Sciaenidae), grunts (Haemulidae), striped anchovies (Engraulidae), shrimp, and squid. 

Bluefish are cannibalistic and can destroy their own young. Bluefish sometimes chase bait through the surf zone, attacking schools in very shallow water, churning the water like a washing machine. This behavior is sometimes referred to as a "bluefish blitz".', 'Ocean', 'Speed', '31 lb 12 oz,
James Hussey,
Hatteras, North Carolina, USA,
1/30/1972', 'Bluefish WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight_lbs, known_for, world_record, world_record_link)
VALUES ('Salt', 'Cobia', 'Black Kingfish, Black Salmon, Ling, Lemonfish, Ccrabeater, Prodigal Son, Black Bonito, Aruan Tasek', 'Attaining a maximum length of 78 in (2 m) and maximum weight of 172 lb (78 kg), the cobia has an elongated fusiform (spindle-shaped) body and a broad, flattened head. The eyes are small and the lower jaw projects slightly past the upper. Fibrous villiform teeth line the jaws, the tongue, and the roof of the mouth. The body of the fish is smooth with small scales. It is dark brown in color, grading to white on the belly with two darker brown horizontal bands on the flanks. The stripes are more prominent during spawning, when they darken and the background color lightens.

The large pectoral fins are normally carried horizontally, perhaps helping the fish attain the profile of a shark. The first dorsal fin has six to 9 independent, short, stout, sharp spines. The family name Rachycentridae, from the Greek words rhachis ("spine") and kentron ("sting"), was inspired by these dorsal spines. Mature cobia have a forked, slightly lunated tail, which is usually dark brown. Juvenile cobia are patterned with conspicuous bands of black and white and have a rounded tail. The largest cobia taken on rod and reel came from Shark Bay, Australia, and weighed 135 lb (60 kg).', 'Rachycentridae', 'Rachycentron canadum', 'Least Concern', 'The cobia is normally solitary except for annual spawning aggregations, and sometimes it will congregate at reefs, wrecks, harbours, buoys, and other structural oases. It is pelagic, but it may enter estuaries and mangroves in search of prey.

It is found in warm-temperate to tropical waters of the West and East Atlantic Ocean, throughout the Caribbean, and in the Indo-Pacific off India, Australia and Japan.', 'Cobia are large, strong gamefish which make determined runs and occasional jumps. 

Cobia are generally caught from boats, piers, and beaches with the most popular tackle being heavy spinning gear designed to cast 15-25 lb test monofilament lines.

Large plugs, similar to those used for striped bass in blue scale or sliver-flash finishes, and 11.5-3 oz jigs with white or yellow skirts are standard baits. A 3 ft wire leader or a 60-80 lb monofilament shock tippet is necessary.

Cobia are typically sighted  near the surface along the coast and often quite close to shore with the ability to spot the fish from long distances being an angler advantage. A beach buggy or a tower equipped boat are often used by cobia angling aficionados.', 'In the southern US, Cobia spawn during the early summer months.

Growth is rapid. Some fish reach 20 inches before their first birthday. By age two, the average size is about 35 inches, although some fish are up to 44 inches long. Most fish caught by fishermen are between 2 and 5 years old, although cobia can live 11 years. 

Females grow faster and larger than males. Research indicates that of fish over 40 inches long, 85% are females.', 'Cobia are not bashful feeders, chasing down food from the top to the bottom of the sea. They seem to especially prefer crabs. Cobia raised in captivity will not grow well unless they are fed some crabs and research indicates that over 70% of their diet is made up of swimming crabs, such as the blue crab. Researchers have found very few shrimp in their stomachs, but finfish were important. By far the most common were hardhead catfish, followed by eels, and then round scad. As cobia grow larger, a greater percentage of their diet is made up of finfish. Feeding seems to slow at lower water temperatures.', 'Ocean', '50-80', 'Stamina', '135 lb 9 oz,
Peter Goulding,
Shark Bay, W.A., Australia,
7/9/1985', 'Cobia WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Skate, Winter', 'Big Skate, Spotted Skate, Eyed Skate', 'Skates are a relative of sharks and rays and have a kite-like shape. Most skates are light brown and covered with small dark spots with mall spines covering most of their back. Skates can have large bodies and grow up to 5 feet in length. Some skates can grow up to 5 feet in length and live for about 20 years.', 'Rajidae', 'Leucoraja ocellata', 'Endangered', 'The winter skate ranges from the Gulf of Saint Lawrence in Canada to Cape Hatteras, North Carolina. 

Skate live on sand and gravel bottoms in the northwest Atlantic, most commonly in southern New England and on Georges Bank. They are occasionally found in the Gulf of Maine, on the Scotian Shelf, in the Gulf of Saint Lawrence, and in the Mid-Atlantic.

Skates are not known to migrate far, but they do move with the seasons as water temperature changes. They are generally offshore during the summer and early autumn and inshore during winter and spring.', 'When angling for any skate use appropriate tackle - IGFA 30lb class gear should be regarded as the absolute minimum to use. Ideally 50-80lb Class should be used. This is as much to combat the ''inhospitable'' conditions in the areas where skate are targeted. i.e. deep water, strong tides. The use of heavier gear allows the skate to be landed more quickly, i.e. not exhausted, allowing it to be released in better condition.

You can land skate on lighter gear but you are not doing yourself or more importantly the fish any favours. Many anglers don''t use anything less than 50lb class, with 80lb being the norm meaning the odds are on your side that the fish will be boated with the minimal chance of a hook being left in the fish

Terminal tackle needs to be strong and is best kept simple. A single 12/0 bronzed hook (e.g. Mustad 3406), preferably with the barb crushed down is best. Never use stainless or plated hooks, as these will not biodegrade if they have to be left in a skate. Keep hook links short (maximum of 24"/60cm). Short hook links are necessary to minimise the chances of deep hooking your skate. These should be made up of 150lb (minimum) breaking strain monofilament, (there is absolutely no need for wire) crimped to a quality 200lb rated swivel. This hook link should then be attached to an 8'' (2.4m) rubbing leader or ''wind on leader'' ( How to make Wind on leader ) made of 150lb b.s. monofilament. This is to protect the mainline from the sharp thorns on the skate''s tail. This leader also helps when bringing the skate to the side of the boat. How to make a skate friendly trace.

The weight boom runs on the heavy mono of the rubbing leader / wind on leader, the main reason for this is to avoid it damaging the mainline and also to assist in keeping the mainline well away from the Skate''s sharp tail thorns.

Common Skate are not fussy eaters and have a very varied menu; this covers most shellfish and fish species. As an apex predator, Common Skate are deceivably agile when it comes to hunting and can easily catch fast swimming species like Herring & Mackerel. More common fodder fish species are Spurdog, Rays, Dogfish and Whiting with Edible Crabs, Prawns, Squat Lobsters and Scallops making up the bulk of the shellfish fodder species.

The most commonly used baits are Mackerel and Coalfish around the 1lb to 1.5lb mark.

Always set the hook as quickly as possible - never wait for a run to develop as this will almost always result in a deep throat hooking of the fish. Don''t worry about missing a bite; skate can and do, swallow very big baits in seconds and if you do miss one, they almost always come back for a second, third or even fourth attempt at a bait.

A lot has been said about the “lack of” fight from Common Skate, this usually comes from people that have either never caught one or have been using mono rather than braid as a the main line. With mono the stretch takes most of the fight out of the encounter, giving the angler very little “feel” as to what is happening at the other end of his line. However with braid you are in full contact with the fish at all times, making the fight rather more interesting.

When a skate is brought to the side of the boat, it can be held quite easily by holding the trace and then getting a firm handhold at the cheek area of the skate. Large specimens may require to be gaffed to aid holding the fish. This needs to be done with great care. The gaff should be used only in the area outside the halfway point of the leading edge of the wing and no more than 3" from the leading edge. This gives a secure hold and poses no danger to internal organs.', 'Winter skates reproduce at a late age, when they’re approximately 11 years old and 2.5 feet long. They lay eggs year-round but have few offspring. Their eggs are enclosed in a hard leathery case called a “mermaid’s purse.” The eggs incubate for 6 to 12 months, and young skates have the adult form when they hatch.', 'Skates feed on a variety of organisms such as crustaceans, mollusks, worms, squids, and fish.', 'Ocean', 'Subpar Game Qualities', '214 lb,
Jan Olsson,
Scapa Flow, Orkney, United Kingdom,
6/16/1968', 'Skate WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, avg_adult_weight_lbs, avg_adult_length_inches, known_for, world_record, world_record_link)
VALUES ('Salt', 'Salmon, Atlantic', 'Bay Salmon, Black Salmon, Caplin-Scull Salmon, Landlocked Salmon, Sebago Salmon, Silver Salmon, Fiddler, Outside Salmon, Grilse, Kelt, Grayling, Smolt, Parr, Slink', 'The Atlantic salmon (Salmo salar) is a fish in the family Salmonidae, which is found in the northern Atlantic Ocean and in rivers that flow into the north Atlantic and, due to human introduction, the north Pacific.

At different points in their maturation and life cycle, they are known as parr, smolt, grilse, grilt, kelt, slink, and spring salmon. Atlantic salmon that do not journey to sea, usually because of past human interference, are known as landlocked salmon or ouananiche.

The Atlantic salmon has the body shape of a trout, and is distinguished from trouts of the genus Oncorhynthus by coloration, size, and location of occurrence, among other things. At sea it is a silvery fish with a sparse scattering of small black spots often shaped like X''s or Y''s on the upper half of the body, and sometimes with a few spots on the cheek and gill cover. In inland waters, especially at spawning time, the Atlantic salmon turns a much darker color of bronze or dark brown. This change may be accompanied by the appearance of red spots on the head and body, making this fish look remarkably like a brown trout (Salmo trutta), its closest relative. Often brown trout may have circles, or halos, around some of its spots and the spotting may be heavier than in the Atlantic salmon, extending onto the lower half of the sides and the fins including the adipose fin. The spots do not normally take the form of X''s or Y''s.', 'Salmonidae', 'Salmo salar', 'Least Concern', 'The Atlantic salmon is native to the northern Atlantic from the Connecticut River to Quebec, Iceland and southern Greenland. It also occurs from the Arctic Circle to Portugal. 

Inland, there are a number of landlocked populations that must be considered strictly freshwater fish. Otherwise, the species is anadromous (migrates to the sea and back, and spawns in fresh water).

The distribution of Atlantic salmon depends on water temperature. Because of global warming, some southern populations in Spain and other warm countries are expected to be extirpated soon. Before human influence, the natural breeding grounds of Atlantic salmon were rivers in Europe and the eastern coast of North America. When North America was settled by Europeans, eggs were brought on trains to the west coast and introduced into the rivers there. Other attempts to bring Atlantic salmon to new settlements were made; e.g. New Zealand. But since there are no suitable ocean currents on New Zealand, most of these introductions failed. There is at least one landlocked population of Atlantic salmon on New Zealand, where the fish never go out to sea', 'Atlantic salmon may be legally taken with spoons, plugs, and live baits however its chief angling value is to the fly fisher. The quality of the sport however varies with the location and the season. 

All salmon rivers do not fish well to the fly because of the their size and turbulence or prevailing weather conditions. Thus, a premium is placed on first-class water and the cost of angling is often expensive.

In the United States only the state of Main provides Atlantic Salmon fishing so the angler must travel long distances in the known periods that correspond with a run of fish.

While on their spawning run Atlantic salmon do not feed, but will often strike aggressively at artificial flies.  

Anglers typically have luck using the same trolling methods that work for chinook and coho.', 'Unlike Pacific salmons (Oncorhynchus spp.), Atlantic salmon spawn more than once before dying.

	Atlantic salmon spend 2-3 years in freshwater, then migrate to the ocean where they spend an additional 2-3 years. They then return to their natal river to spawn and rear juveniles in rivers before feeding and migrating back to the high seas.

Suitable spawning habitat consists of gravel or rubble in areas of moving water. Eggs hatch in March or April and become fry.

Fry remain buried in the gravel for about six weeks. The fry emerge from the gravel about mid-May and start feeding on plankton and small invertebrates. Emergent fry quickly disperse from nests (called redds) within the gravel. They develop camouflaging stripes along their sides, and enter what is termed the parr stage.

Parr habitat, often called "nursery habitat," is typically riffle areas characterized by adequate cover, shallow water depth, and moderate to fast water flow.

Salmon parr spend 2-3 years in freshwater and then undergo a physiological transformation called smoltification that prepares them for life in a marine habitat.

Atlantic salmon leave Maine rivers in the spring and reach Newfoundland and Labrador by mid-summer. They spend their first winter at sea south of Greenland.

After the first winter at sea, a small percentage return to Maine while the majority spend a second year at sea, feeding off the southwest or, to a much lesser extent, the southeast coast of Greenland. Some Maine salmon are also found in waters along the Labrador coast.

After a second winter in the Labrador Sea, most Maine salmon return to rivers in Maine, with a small number returning the following year as what is referred to as three sea winter fish.', 'Young salmon begin a feeding response within a few days. After the yolk sac is absorbed by the body, they begin to hunt. Juveniles start with tiny invertebrates, but as they mature, they may occasionally eat small fish. During this time, they hunt both in the substrate and in the current. Some have been known to eat salmon eggs. The most commonly eaten foods include caddisflies, blackflies, mayflies, and stoneflies.

As adults, the fish feed on much larger food: Arctic squid, sand eels, amphipods, Arctic shrimp, and sometimes herring, and the fishes'' size increases dramatically.', 'Ocean', 10, 30, 'Fight Dynamics', '79 lb 2 oz,
Henrik Henriksen,
Tana River, Norway,
1/1/1928', 'Atlantic Salmon WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Salmon, Chinook', 'King Salmon, Tyee Salmon, Columbia River Salmon, Black Salmon, Chub Salmon, Hook Bill Salmon, Winter Salmon, Blackmouth', 'One of the world’s most valuable species commercially and recreationally, chinook (aka king) salmon are easily the largest of six Pacific salmon species.

Chinook salmon are very similar to coho salmon in appearance while at sea (blue-green back with silver flanks), except for their large size, small black spots on both lobes of the tail, and black pigment along the base of the teeth.

The IGFA all-tackle record came from Alaska’s Kenai River in 1985, weighing 97 pounds, 4 ounces.', 'Salmonidae', 'Oncorhynchus tshawytscha', 'Not Evaluated', 'Historically, the native distribution of Chinook salmon in North America ranged from the Ventura River in California in the south to Kotzebue Sound in Alaska in the north. Populations have disappeared from large areas where they once flourish, however,shrinking by as much as 40 percent. In some regions, their inland range has been cut off, mainly by dams and habitat alterations: from Southern California, some areas east of the Coast Ranges of California and Oregon, and large areas in the Snake River and upper Columbia River drainage basins.

In the western Pacific, the distribution ranges from northern Japan (Hokkaido) in the south to the Arctic Ocean as far as the East Siberian Sea and Palyavaam River in the north. Nevertheless, they are consistently present and the distribution is well known only in Kamchatka. Elsewhere, information is scarce, but they have a patchy presence in the Anadyr River basin and parts of the Chukchi Peninsula. Also in parts of the northern Magadan Oblast near the Shelikhov Gulf and Penzhina Bay stocks might persist, but remain poorly studied.', 'Anglers generally troll for a combination of wild and hatchery chinook, using herring, anchovies, plastic squid (Hoochys) and hard plugs, often on downriggers set at 50 to 200 feet.', 'Chinook may spend one to eight years in the ocean (averaging from three to four years) before returning to their home rivers to spawn. 

Chinook spawn in larger and deeper waters than other salmon species and can be found on the spawning redds (nests) from September to December. 

After laying eggs, females guard the redd from four to 25 days before dying, while males seek additional mates. 

Chinook eggs hatch, depending upon water temperature, 90 to 150 days after deposition. Egg deposits are timed to ensure the young salmon fry emerge during an appropriate season for survival and growth. Fry and parr (young fish) usually stay in fresh water 12 to 18 months before traveling downstream to estuaries, where they remain as smolts for several months. 

Some Chinooks return to the fresh water one or two years earlier than their counterparts, and are referred to as "jack" salmon. "Jack" salmon are typically less than 24 in long, but are sexually mature and return at an earlier age.

The Yukon River has the longest freshwater migration route of any salmon, over 3,000 km (1,900 mi) from its mouth in the Bering Sea to spawning grounds upstream of Whitehorse, Yukon. 

Since Chinook rely on fat reserves for energy upon entering fresh water, commercial fish caught here are highly prized for their unusually high levels of heart-healthy omega-3 fatty acids. However, the high cost of harvest and transport from this exceptionally rural area limits its affordability. 

The highest in elevation Chinook migrate to spawn is in the Upper Salmon River and Middle Fork of the Salmon River in Idaho. These anadromous fish travel over 7,000 ft in elevation past and over 900 statute miles, in their migration through eight dams and reservoirs on the Columbia and Lower Snake Rivers.

Chinook juveniles divide into two types: ocean-type and stream-type. Ocean-type chinook migrate to salt water in their first year. 

Stream-type salmon spend one full year in fresh water before migrating to the ocean. After a few years in the ocean, adult salmon, then large enough to escape most predators, return to their original streambeds to mate. 

Chinook can have extended lifespans, where some fish spend one to five years in the ocean, reaching age eight. More northerly populations tend to have longer lives.

Chinook Salmon need an adequate spawning habitat. Clean, cool, oxygenated, sediment-free fresh water is essential for egg development. Chinook use larger sediment (gravel) sizes for spawning than other Pacific salmon. 

Riparian vegetation and woody debris help juvenile salmon by providing cover and maintaining low water temperatures.', 'Chinook eat insects, amphipods, and other crustaceans while young, and primarily other fish when older. Young salmon feed in streambeds for a short period until they are strong enough to journey out into the ocean and acquire more food.', 'Ocean', 'Stamina', '97 lb 4 oz,
Les Anderson,
Kenai River, Alaska, USA,
5/17/1985', 'Chinook Salmon WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Salmon, Coho', 'Silver Salmon, Hook Nose Salmon, Blueback Salmon, Jack Salmon, Salmon Trout, Siverside Salmon, White Salmon.', 'During their ocean phase, coho salmon have silver sides and dark-blue backs. During their spawning phase, their jaws and teeth become hooked. After entering fresh water, they develop bright-red sides, bluish-green heads and backs, dark bellies and dark spots on their backs. Sexually maturing fish develop a light-pink or rose shading along the belly, and the males may show a slight arching of the back. Mature adults have a pronounced red skin color with darker backs and average 28 inches (71 cm) and 7 to 11 pounds (3.2 to 5.0 kg), occasionally reaching up to 36 pounds (16 kg). They also have a large kype (or hook on th elower jaw) during spawning. Mature females may be darker than males, with both showing a pronounced hook on the nose.', 'Salmonidae', 'Oncorhynchus kisutch', 'Not Evaluated', 'The traditional range of the coho salmon runs along both sides of the North Pacific Ocean, from Hokkaidō, Japan and eastern Russia, around the Bering Sea to mainland Alaska, and south to Monterey Bay, California. Coho salmon have also been introduced in all the Great Lakes, as well as many landlocked reservoirs throughout the United States.', 'While considerably smaller than chinook, coho salmon are more abundant and qualify as one of the world’s great light-tackle gamefish. 

In North America, the coho salmon is a game fish in fresh and salt water from July to December, especially with light fishing tackle. It is one of the most popular sport fish in the Pacific Northwest of the United States and Canada. Its popularity is due in part to the reckless abandon which it frequently displays chasing bait and lure while in salt water, and the large number of coastal streams it ascends during its spawning runs. Its habit of schooling in relatively shallow water, and often near beaches, makes it accessible to anglers on the banks, as well as in boats.', 'The eggs hatch in the late winter or early spring after six to seven weeks in the redd. Once hatched, they remain mostly immobile in the redd during the alevin life stage, which lasts for 6–7 weeks. Alevin no longer have the protective egg shell, or chorion, and rely on their yolk sacs for nourishment during growth. The alevin life stage is very sensitive to aquatic and sedimental contaminants. When the yolk sac is completely resorbed, the alevin leaves the redd. 

Young coho spend one to two years in their freshwater natal streams, often spending the first winter in off-channel sloughs, before transforming to the smolt stage. 

Smolts are generally 100–150 mm (3.9–5.9 in) and as their parr marks fade and the adult''s characteristic silver scales start to dominate. Smolts migrate to the ocean from late March through July. Some fish leave fresh water in the spring, spend summer in brackish estuarine ponds, and then return to fresh water in the fall. 

Coho salmon live in salt water for one to three years before returning to spawn. Some precocious males, known as "jacks", return as two-year-old spawners. Spawning males develop kypes, which are strongly hooked snouts and large teeth.', 'Young coho in freshwater feed on plankton and insects. When they reach the ocean, their diet consists of herring, pilchards, sand lance, squid and crustaceans. 

Coho that live only in freshwater also eat plankton and insects in their youth and baitfish once they reach maturity (usually alewives and smelt). Coho were actually introduced to keep populations of baitfish under control.', 'Ocean', 'Aerial Acrobatics', '33 lb 4 oz,
Jerry Lifton,
Salmon River, Pulaski, NY, USA
9/27/1989', 'Coho Salmon WR');

INSERT INTO fish_species (class, common_name, also_known_as, description, family, species, environmental_status, habitat, fishing_techniques, spawning_habits_lifecycle, diet_feeding_habits, water_body_type, known_for, world_record, world_record_link)
VALUES ('Salt', 'Drum, Red', 'Channel Bass, Redfish, Spottail Bass, Red', 'A cousin to the black drum, the red drum is one of the most accessible fish species available from the westernmost Gulf of Mexico to the mid-Atlantic states which has helped account for its tremendous popularity among nearshore and inshore anglers.

The Red drum has a large scaled red to copper-bronze body which fades into white on the belly and presents in lighter shades in clear waters. Red drum typically have one to many spots at the base of the tail, rarely having no spots. The mouth is horizontal and opens downward accompanied by a chin without barbels.

The all-tackle record weighed 94 pounds, 2 ounces, from North Carolina in 1984.', 'Sciaenidae', 'Sciaenops ocellatus', 'Least Concern', 'Red drum occur naturally along the southern Atlantic and Gulf of Mexico coasts of the United States, including the coasts of Louisiana, Texas, Alabama, Mississippi, and Florida.

Aquaculture activities involving Red Drum occur around the world. Immature red drum prefer grass marsh areas of bays and estuaries when available. Both younger mature red drum (3-6 years of age) and bull red drum prefer rocky outcroppings including jetties and manmade structures, such as oil rigs and bridge posts. Around this type of structure, they are found throughout the water column.', 'Redfish are very wary and will spook very easily. This is especially true in shallow or very clear water. Approach quietly with a push pole taking extra care not to make any unnecessary noises.

Incoming tides bring with it food, bait fish, etc. that the Redfish will feed on. Also, small crabs and shrimp become more active on the incoming tide enticing the Redfish to feed at those locations. The opposite is true for outgoing tides – as the water withdraws, the Redfish will wait and feed on whatever bait is carried back out with the tide. Channels and deeper areas are good places to find Redfish on an outgoing tide. Work these locations for some terrific action.

Shrimp, pinfish, small crabs, finger mullet, and cut baits are excellent for catching Redfish. They can be fished under a float or free-lined into currents past structures or grass flats where the fish are.

There are several artificial lures that work well in catching Redfish. They include a gold spoon, several varieties of MurroLure, and jigs. Fish these around structures during rising and falling tides.

Tackle selection could include spinning or baitcasting gear, 10 to 20 lb rating and a 1/0 to 4/0 hook.', 'Mature red drum spawn in near shorelines from mid-August to mid-October. The red drum''s eggs incubate for 24 hours. A female lays about 1.5 million (with a range of 200,000 up to more than three million) eggs per batch. 

It was reported that in the first year, young red drum in Texas estuaries grew about 0.6 mm per day, though the rates varied with location and year and were higher in more southerly estuaries. After the first year they may be 10 – 15 in long. About half of red drum are able to reproduce by the age of 4, when they are 25-30 in long and 7.5 – 9 lb in weight. Red drum live to be 60 years old unless caught.', 'The diet of red drum showed significant seasonal patterns, and was dominated by white shrimp (Penaeus setiferus) during fall and gulf menhaden (Brevoortia patronus) during spring. Blue crab (Callinectes sapidus) was an important component of red drum diets during both seasons. Significant differences existed between prey types consumed during fall and spring as red drum diet reflected seasonal variation in prey availability.', 'Ocean', 'Sight Casting Target', '94 lb 2 oz,
David Deuel,
Avon, North Carolina, USA	,
11/7/1984', 'Red Drum WR');
